// 予約サイトの入口（express）
import express from 'express';
import { reserveButton } from './reserve';

const app = express();
app.get('/', (_req, res) => {
  const b = reserveButton(12);
  res.send(`<h1>港の予約</h1><button${b.disabled ? ' disabled' : ''}>${b.label}</button>`);
});
app.get('/health', (_req, res) => res.json({ status: 'ok' }));
app.listen(3000);

