// 予約のボタン。空きが無い時だけ押せなくする
export function reserveButton(seatsLeft: number) {
  return { label: '予約する', disabled: seatsLeft === 0 };
}

import { expect, test } from 'vitest';
import { reserveButton } from '../src/reserve';

test('予約のボタン: 空きがあれば押せる', () => {
  expect(reserveButton(3).disabled).toBe(false);
});

test('予約のボタン: 満席なら押せない', () => {
  expect(reserveButton(0).disabled).toBe(true);
});
